window.ScripturaLexicons.BDAG_PART_0376 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-01\" data-source=\"BDAG\" data-search=\"φελόνης remissão v. φαιλόνης BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φελόνης</td><td>remissão</td><td>v. φαιλόνης</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-02\" data-source=\"BDAG\" data-search=\"φέρω verbo levar; trazer; conduzir; sustentar; suportar; produzir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φέρω</td><td>verbo</td><td>levar; trazer; conduzir; sustentar; suportar; produzir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-03\" data-source=\"BDAG\" data-search=\"φεύγω verbo fugir; escapar; evitar; desaparecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φεύγω</td><td>verbo</td><td>fugir; escapar; evitar; desaparecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-04\" data-source=\"BDAG\" data-search=\"Φῆλιξ, ικος, ὁ nome próprio masculino Félix BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Φῆλιξ, ικος, ὁ</td><td>nome próprio masculino</td><td>Félix</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-05\" data-source=\"BDAG\" data-search=\"φήμη, ης, ἡ substantivo feminino notícia; relato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φήμη, ης, ἡ</td><td>substantivo feminino</td><td>notícia; relato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-06\" data-source=\"BDAG\" data-search=\"φημί verbo dizer; afirmar; querer dizer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φημί</td><td>verbo</td><td>dizer; afirmar; querer dizer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-07\" data-source=\"BDAG\" data-search=\"φημίζω verbo difundir notícia; propalar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φημίζω</td><td>verbo</td><td>difundir notícia; propalar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-08\" data-source=\"BDAG\" data-search=\"Φῆστος, ου, ὁ nome próprio masculino Festo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Φῆστος, ου, ὁ</td><td>nome próprio masculino</td><td>Festo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-09\" data-source=\"BDAG\" data-search=\"φθάνω verbo preceder; chegar; alcançar; atingir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθάνω</td><td>verbo</td><td>preceder; chegar; alcançar; atingir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-10\" data-source=\"BDAG\" data-search=\"φθαρ- remissão v. φθείρω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθαρ-</td><td>remissão</td><td>v. φθείρω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-11\" data-source=\"BDAG\" data-search=\"φθαρτός, ή, όν adjetivo; substantivado perecível; mortal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθαρτός, ή, όν</td><td>adjetivo; substantivado</td><td>perecível; mortal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-12\" data-source=\"BDAG\" data-search=\"φθέγγομαι verbo falar; proferir; proclamar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθέγγομαι</td><td>verbo</td><td>falar; proferir; proclamar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-13\" data-source=\"BDAG\" data-search=\"φθείρω verbo destruir; arruinar; corromper; violar regras BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθείρω</td><td>verbo</td><td>destruir; arruinar; corromper; violar regras</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-14\" data-source=\"BDAG\" data-search=\"φθινοπωρινός, ή, όν adjetivo do fim do outono BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθινοπωρινός, ή, όν</td><td>adjetivo</td><td>do fim do outono</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-15\" data-source=\"BDAG\" data-search=\"φθόγγος, ου, ὁ substantivo masculino som; tom BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθόγγος, ου, ὁ</td><td>substantivo masculino</td><td>som; tom</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-16\" data-source=\"BDAG\" data-search=\"φθονέω verbo invejar; ter ciúme; ressentir-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθονέω</td><td>verbo</td><td>invejar; ter ciúme; ressentir-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-17\" data-source=\"BDAG\" data-search=\"φθόνος, ου, ὁ substantivo masculino inveja; ciúme BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθόνος, ου, ὁ</td><td>substantivo masculino</td><td>inveja; ciúme</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-18\" data-source=\"BDAG\" data-search=\"φθορά, ᾶς, ἡ substantivo feminino deterioração; aborto; sedução; depravação; destruição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθορά, ᾶς, ἡ</td><td>substantivo feminino</td><td>deterioração; aborto; sedução; depravação; destruição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-19\" data-source=\"BDAG\" data-search=\"φθορεύς, έως, ὁ substantivo masculino sedutor; corruptor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθορεύς, έως, ὁ</td><td>substantivo masculino</td><td>sedutor; corruptor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0376-20\" data-source=\"BDAG\" data-search=\"φθοριμαῖος, α, ον adjetivo destrutivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φθοριμαῖος, α, ον</td><td>adjetivo</td><td>destrutivo</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0376-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φελόνης</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φελόνης</span> v. <span class=\"greek\">φαιλόνης</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φέρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φέρω</span> (Hom.+) imperf. <span class=\"greek\">ἔφερον</span>; fut. <span class=\"greek\">οἴσω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:26</a>; 1.º aor. <span class=\"greek\">ἤνεγκα</span>, part. <span class=\"greek\">ἐνέγκας</span>; 2.º aor. inf. <span class=\"greek\">ἐνεγκεῖν</span> (B-D-F §81, 2); perf. <span class=\"greek\">ἐνήνοχα</span> (LXX, JosAs). Pass.: 1.º aor. <span class=\"greek\">ἠνέχθην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:17,</a> 21a, 3.ª pl. <span class=\"greek\">ἐνέχθησαν</span> Hs 8, 2, 1.</p><p class=\"entry-text\">① levar ou carregar de um lugar a outro, com ênfase no ato de transporte</p><p class=\"entry-text\">ⓐ lit.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. carregar, levar (Aristoph., Ra. [Rãs] 27 <span class=\"greek\">τὸ</span> <span class=\"greek\">βάρος</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">φέρεις</span>; X., Mem. 3, 13, 6 <span class=\"greek\">φορτίον</span> <span class=\"greek\">φέρειν</span>; GrBar 12:1 <span class=\"greek\">κανίσκια</span> ‘cestos’) <span class=\"greek\">ἐπέθηκαν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σταυρὸν</span> <span class=\"greek\">φέρειν</span> <span class=\"greek\">ὄπισθεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:26</a> (v. <span class=\"greek\">σταυρός</span> 1).—Em imagem extraída de Gen 2 <span class=\"greek\">οὗ</span> <span class=\"greek\">ξύλον</span> <span class=\"greek\">φέρων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καρπὸν</span> <span class=\"greek\">αἱρῶν</span> se carregares a árvore (da palavra) e colheres seu fruto Dg 12:8. Para Papias (3:2), v. 3a.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. trazer consigo, trazer/levar junto (Diod S 6, 7, 8 <span class=\"greek\">γράμματα</span> <span class=\"greek\">φέρων</span>; GrBar 12:7 <span class=\"greek\">φέρετε</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἠνέγκατε</span> ‘trazei aqui o que trouxestes’, para a nuance de <span class=\"greek\">φέρετε</span> v. 2a; PTebt 418, 9; 421, 6; 8) <span class=\"greek\">φέρουσαι</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">ἡτοίμασαν</span> <span class=\"greek\">ἀρώματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:1.</a> Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:39.</a></p><p class=\"entry-text\">ⓑ fig.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. carregar um fardo <span class=\"greek\">οὗτος</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">φέρει</span> 1 Cl 16:4 (Is 53:4).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. portar um nome <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> portar o nome do Senhor, isto é, de um cristão Pol 6:3 (cf. Just., D. 35, 6).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. trazer/conceder um favor <span class=\"greek\">χάριν</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">φέρειν</span> (Il. 5, 211; Od. 5, 307; cf. Aeschyl., Ag. 421f; mas não Andoc., De Reditu 9 ‘expressar gratidão’) <span class=\"greek\">ἐλπίσατε</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φερομένην</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀποκαλύψει</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> esperai pelo favor que vos está sendo concedido em conexão com a revelação de Jesus Cristo (isto é, quando ele for revelado) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:13.</a></p><p class=\"entry-text\">② fazer uma entidade mover-se de uma posição a outra, com ênfase na apresentação ou realização de algo</p><p class=\"entry-text\">ⓐ uma coisa, trazer (sobre), produzir (GrBar 12:7 <span class=\"greek\">φέρετε</span> ‘trazei aqui’ [o que trouxestes convosco, v. 1a<span class=\"greek\">β</span>])</p><p class=\"entry-text\"><span class=\"greek\">α</span>. trazer (a), buscar <span class=\"greek\">τὶ</span> algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:27,</a> 28 (<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πίνακι</span>. Sobre trazer uma cabeça a um banquete, cf. Diog. L. 9, 58: a presença de uma cabeça decepada não perturbava necessariamente o ambiente de uma refeição. Appian, Bell. Civ. 4, 20, §81 relata a respeito de Antônio que ele mandou colocar a cabeça de Cícero <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τραπέζης</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:7</a> D; 15:22 v.l. por <span class=\"greek\">ἐξ</span>-; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:34,</a> 37; 5:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:13</a>; B 2:5; MPol 11:2; Hs 8, 1, 16 (com duplo acus., de objeto e predicativo); 9, 10, 1; <span class=\"greek\">δῶρα</span> GJs 1:2; 5:1. Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:11a</a> (<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πίνακι</span>); Hv 3, 2, 7; 3, 5, 3; Hs 8, 2, 1ab; 9, 4, 7; 9, 6, 5–7; 9, 9, 4f. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> (JosAs 16:1 <span class=\"greek\">φέρε</span> <span class=\"greek\">δή</span> <span class=\"greek\">μοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κηρίον</span> <span class=\"greek\">μέλιτος</span>; ApcMos 6) algo a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:18</a> (com <span class=\"greek\">ὧδε</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:15.</a> <span class=\"greek\">θυσίαν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> 1 Cl 4:1 (v. Gen 4:3; cf. Just., A I, 24, 2 <span class=\"greek\">θυσίας</span>). O acusativo é suprido pelo contexto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:11b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:8a.</a> O dativo e o acusativo devem ser supridos <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἤνεγκαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:8b.</a> <span class=\"greek\">φέρειν</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> com acusativo da coisa a ser suprido (X., Cyr. 8, 3, 47; Ex 32:2) Hs 8, 4, 3; 9, 10, 2. <span class=\"greek\">φ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">εἰς</span> (1 Km 31:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:24,</a> 26. <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἤνεγκεν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">φαγεῖν</span>; supondes que alguém lhe tenha trazido algo para comer? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:33.</a> V. <span class=\"greek\">φόρος</span>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Fig. ocasionar (Hom.+; Mitt-Wilck. I/2, 284, 11 [II a.C.] <span class=\"greek\">αἰσχύνην</span>; PTebt 104, 30; POxy 497, 4; 1062, 14; Jos., Vi. 93, C. Ap. 1, 319; SibOr 3, 417; Just., A I, 27, 5 [<span class=\"greek\">βλάβην</span>]) <span class=\"greek\">τὸ</span> <span class=\"greek\">βάπτισμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φέρον</span> <span class=\"greek\">ἄφεσιν</span> o batismo que proporciona o perdão B 11:1.</p><p class=\"entry-text\">ⓑ um ser vivo, animal ou humano, conduzir, trazer</p><p class=\"entry-text\"><span class=\"greek\">α</span>. animais (TestAbr A 2 p. 79, 8 [Stone p. 6] <span class=\"greek\">ἵππους</span>; ibid. B 2 p. 106, 21 [Stone p. 60] <span class=\"greek\">μόσχον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:2,</a> 7 (<span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:13</a> (<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πυλῶνας</span>); GJs 4:3.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. pessoas: trazer ou conduzir <span class=\"greek\">τινά</span> alguém <span class=\"greek\">ἀσθενεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:16.</a> <span class=\"greek\">κακούργους</span> GPt 4:10. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κλίνης</span> (Jos., Ant. 17, 197) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:18.</a> <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> alguém a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:17</a> (com <span class=\"greek\">ὧδε</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:32</a>; 8:22. Também <span class=\"greek\">τινὰ</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:32</a>; 2:3; 9:17, 19f. <span class=\"greek\">φέρουσιν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Γολγοθᾶν</span> <span class=\"greek\">τόπον</span> 15:22 (TestAbr A 11 p. 88, 27 [Stone p. 24] <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀνατολήν</span>). <span class=\"greek\">ἄλλος</span> <span class=\"greek\">οἴσει</span> (<span class=\"greek\">σε</span>) <span class=\"greek\">ὅπου</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">θέλεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:18.</a></p><p class=\"entry-text\">③ fazer seguir determinado curso em direção ou conduta, deslocar, impelir; a pass. pode ser traduzida de vários modos: ser movido, ser impelido, deixar-se mover</p><p class=\"entry-text\">ⓐ lit., pelo vento e pelas condições atmosféricas (Apollon. Rhod. 4, 1700; Chariton 3, 5, 1; Appian, Bell. Civ. 1, 62 §278 apesar da tempestade Mário saltou para um barco e <span class=\"greek\">ἐπέτρεψε</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τύχῃ</span> <span class=\"greek\">φέρειν</span> deixou-se levar pela fortuna; Jer 18:14; PsSol 8:2 <span class=\"greek\">πυρὸς</span> … <span class=\"greek\">φερομένου</span>; TestNapht 6:5; Ar. 4, 2 <span class=\"greek\">ἄστρα</span> … <span class=\"greek\">φερόμενα</span>; Tat. 26, 1 <span class=\"greek\">τῆς</span> <span class=\"greek\">νεὼς</span> <span class=\"greek\">φερομένης</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:15,</a> 17.—Mover-se, passar (v. L-S-J-M s.v. <span class=\"greek\">φέρω</span> B 1) <span class=\"greek\">φέρεσθαι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">αὐτοῦ</span> … <span class=\"greek\">ἰχῶρας</span> secreções fétidas eram expelidas … por ele (o pênis de Judas) Papias (3:2).</p><p class=\"entry-text\">ⓑ fig., do Espírito de Deus, pelo qual as pessoas são movidas (cf. Job 17:1 <span class=\"greek\">πνεύματι</span> <span class=\"greek\">φερόμενος</span>) <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">φερόμενοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:21b.</a> Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:29</a> D. <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">φερόμενος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Παῦλος</span> AcPl Ha 5, 1. Do impulso para fazer o bem Hs 6, 5, 7. Dos poderes do mal (Ps.-Plut., Hom. 133 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ὀργῆς</span> <span class=\"greek\">φερόμενοι</span>; Jos., Bell. 6, 284; Ath. 25, 4) PtK 2 p. 14, 11; Dg 9:1; Hs 8, 9, 3.</p><p class=\"entry-text\">ⓒ também do próprio vento (Ptolem., Apotel. 1, 11, 3 <span class=\"greek\">οἱ</span> <span class=\"greek\">φερόμενοι</span> <span class=\"greek\">ἄνεμοι</span>; Diog. L. 10, 104 <span class=\"greek\">τ</span>. <span class=\"greek\">πνεύματος</span> <span class=\"greek\">πολλοῦ</span> <span class=\"greek\">φερομένου</span>; Quint. Smyrn. 3, 718) <span class=\"greek\">φέρεσθαι</span> precipitar-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:2.</a></p><p class=\"entry-text\">ⓓ de várias outras entidades: de fragrância <span class=\"greek\">φέρεσθαι</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> ser levada ou transportada pelo ar até alguém (Dio Chrys. 66 [16], 6 ‘precipitar-se sobre alguém’) ApcPt 5:16.—De escritos (Diog. L. 5, 86 <span class=\"greek\">φέρεται</span> <span class=\"greek\">αὐτοῦ</span> [isto é, Heraclid. Pont.] <span class=\"greek\">συγγράμματα</span> <span class=\"greek\">κάλλιστα</span>; Marinus, Vi. Procli 38; cf. Arrian, Anab. 7, 12, 6 <span class=\"greek\">λόγος</span> <span class=\"greek\">ἐφέρετο</span> <span class=\"greek\">Ἀλεξάνδρου</span>=circulava um dito de Alexandre) <span class=\"greek\">οὗ</span> (=<span class=\"greek\">τοῦ</span> <span class=\"greek\">Εἰρηναίου</span>) <span class=\"greek\">πολλὰ</span> <span class=\"greek\">συγγράμματα</span> <span class=\"greek\">φέρεται</span> de quem há muitos escritos em circulação EpilMosq 2.—Do desenvolvimento espiritual <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τελειότητα</span> <span class=\"greek\">φερώμεθα</span> avancemos rumo à perfeição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1.</a></p><p class=\"entry-text\">④ mover um objeto até determinado ponto, pôr, colocar <span class=\"greek\">φέρειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δάκτυλον</span>, <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span> pôr ou estender o dedo, a mão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:27a</a> (<span class=\"greek\">ὧδε</span>), v. 27b.</p><p class=\"entry-text\">⑤ fazer permanecer em um estado ou condição, sustentar, fig., do Filho de Deus <span class=\"greek\">φέρων</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ῥήματι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δυνάμεως</span> <span class=\"greek\">αὐτοῦ</span> que sustenta o universo por sua palavra poderosa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:3</a> (cf. Plut., Lucull. 6, 3 <span class=\"greek\">φέρειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>; Num 11:14; Dt 1:9).</p><p class=\"entry-text\">⑥ proporcionar passagem a um lugar, conduzir a, de uma porta, levar a algum lugar (cf. Hdt. 2, 122; Thu. 3, 24, 1 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">Θήβας</span> <span class=\"greek\">φέρουσαν</span> <span class=\"greek\">ὁδόν</span>; Ps.-Demosth. 47, 53 <span class=\"greek\">θύρα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κῆπον</span> <span class=\"greek\">φέρουσα</span>; SIG 1118, 5; POxy 99, 7; 17 [I d.C.]; 69, 1 [II d.C.] <span class=\"greek\">θύρα</span> <span class=\"greek\">φέρουσα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ῥύμην</span>) <span class=\"greek\">τήν</span> <span class=\"greek\">πύλην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φέρουσαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:10</a> (X., Hell. 7, 2, 7 <span class=\"greek\">αἱ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">φέρουσαι</span> <span class=\"greek\">πύλαι</span>; Diog. L. 6, 78 <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πύλῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φερούσῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰσθμόν</span>; Jos., Ant. 9, 146).—V. Fitzmyer s.v. <span class=\"greek\">ἄγω</span>.</p><p class=\"entry-text\">⑦ pôr em circulação um pensamento ou ideia, trazer, proferir, fazer uma palavra, discurso, anúncio, acusação etc. (TestAbr B 6 p. 110, 8/Stone p. 68 [ParJer 7:8] <span class=\"greek\">φάσιν</span> ‘notícia’; Jos., Vi. 359, C. Ap. 1, 251; Just., A I, 54, 1 <span class=\"greek\">ἀπόδειξιν</span> ‘prova’, A II, 12, 5 <span class=\"greek\">ἀπολογίαν</span>), como expressão judicial (cf. Demosth. 58, 22; Polyb. 1, 32, 4; PAmh 68, 62; 69; 72) <span class=\"greek\">κατηγορίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:29.</a> Cf. Ac 25:7 v.l., 18 (Field, Notes 140); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:11.</a> Talvez caiba aqui <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">κατάγνωσιν</span> <span class=\"greek\">φέρουσιν</span> antes culpam a si mesmos 1 Cl 51:2. <span class=\"greek\">διδαχήν</span> 2J 10. <span class=\"greek\">ὑποδείγματα</span> dar ou oferecer exemplos 1 Cl 55:1 (Polyb. 18, 13, 7 <span class=\"greek\">τὰ</span> <span class=\"greek\">παραδείγματα</span>). <span class=\"greek\">τοῦτο</span> <span class=\"greek\">φέρεται</span> <span class=\"greek\">ἐν</span> isto é apresentado = isto está registrado em EpilMosq 4.—De uma proclamação divina, seja direta ou indireta (Diod S 13, 97, 7 <span class=\"greek\">τ</span>. <span class=\"greek\">ἱερῶν</span> <span class=\"greek\">φερόντων</span> <span class=\"greek\">νίκην</span>; Just., D. 128, 2 <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ὁμιλίας</span> [do Logos]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:17,</a> 18, 21a.</p><p class=\"entry-text\">⑧ demonstrar a realidade de algo, estabelecer <span class=\"greek\">θάνατον</span> <span class=\"greek\">ἀνάγκη</span> <span class=\"greek\">φέρεσθαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαθεμένου</span> a morte de quem fez o testamento deve ser comprovada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:16.</a></p><p class=\"entry-text\">⑨ resistir em face de dificuldade, suportar pacientemente, tolerar, aguentar (X., An. 3, 1, 23; Appian, Samn. 10 §13 <span class=\"greek\">παρρησίαν</span> <span class=\"greek\">φ</span>.=tolerar a franqueza, Iber. 78 §337; Jos., Ant. 7, 372; 17, 342; AssMos Fgm. j <span class=\"greek\">βλασφημίαν</span>; Just., D. 18, 3 <span class=\"greek\">πάντα</span>; Mel., HE 4, 26, 6 <span class=\"greek\">θανάτου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">γέρας</span>) <span class=\"greek\">μαλακίαν</span> 1 Cl 16:3 (Is 53:3). <span class=\"greek\">τὸν</span> <span class=\"greek\">ὀνειδισμὸν</span> <span class=\"greek\">αὐτοῦ</span> (isto é, <span class=\"greek\">Ἰησοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:13</a> (cf. Ezk 34:29). <span class=\"greek\">τὸ</span> <span class=\"greek\">διαστελλόμενον</span> 12:20. <span class=\"greek\">εὐκλεῶς</span> 1 Cl 45:5. De Deus <span class=\"greek\">ἤνεγκεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλῇ</span> <span class=\"greek\">μακροθυμίᾳ</span> <span class=\"greek\">σκεύη</span> <span class=\"greek\">ὀργῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:22.</a> <span class=\"greek\">φῶς</span> <span class=\"greek\">μέγα</span> … <span class=\"greek\">ὥστε</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀφθαλμοὺς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">φέρειν</span> uma luz tão brilhante que seus olhos não podiam suportá-la GJs 19:2.</p><p class=\"entry-text\">⑩ ser produtivo, dar, produzir, de uma planta e de seus frutos, lit. e em imagens (Hom. e outros; Diod S 9, 11, 1; Aelian, VH 3, 18 p. 48, 20; Jo 2:22; Ezk 17:8; Jos., Ant. 4, 100) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:18ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:24</a>; 15:2abc, 4f, 8, 16; Hs 2:3f, 8.—B. 707. DELG. Schmidt, Syn. III 167–93. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φεύγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φεύγω</span> fut. <span class=\"greek\">φεύξομαι</span>; 2.º aor. <span class=\"greek\">ἔφυγον</span>; perf. <span class=\"greek\">πέφυγα</span> LXX (Hom.)</p><p class=\"entry-text\">① buscar segurança na fuga, fugir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:33</a>; 26:56; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:14</a>; 14:50, 52 (a acepção 2 também é possível; cf. PTebt 48, 23f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:12,</a> 13 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:29</a>; GPt 13:57; AcPl Ha 4, 1; 9; 5, 8;12;17; <span class=\"greek\">ἀπό</span> (X., Cyr. 7, 2, 4, Mem. 2, 6, 31; Arrian, Ind. 6, 5; Ex 4:3; 2 Km 19:10; PsSol 17:16; TestDan 5:1; JosAs 5:2 [<span class=\"greek\">ἀπὸ</span> <span class=\"greek\">προσώπου</span>]; Jos., Bell. 1, 474) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:7</a>=Hm 12, 4, 7; cf. 12, 5, 2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:6</a> (a morte lhes escapará); 1 Cl 4:10; 28:2; Hm 11:14; 12, 2, 4 (com <span class=\"greek\">μακράν</span>). <span class=\"greek\">ἐκ</span> (Ael. Aristid. 30 p. 583 D.; Jos., Ant. 14, 177) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:30.</a> <span class=\"greek\">εἰς</span> (X., Mem. 1, 2, 24; Gen 14:10; Num 24:11; JosAs 28:7 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὕλην</span>; Demetr.: 722 Fgm. 1, 1 Jac.; Jos., Ant. 14, 418 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄρη</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:13</a>; 10:23; 24:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:21</a> (cf. 1 Macc 2:28); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:15</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:6.</a> <span class=\"greek\">ἐπί</span> com acus. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄρη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:16</a> v.l. (X., Ages. 2, 11; JosAs 27:7 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὕλην</span>).—RBach, Die Aufforderungen zur Flucht und zum Kampf im alttestamentlichen Prophetenspruch ’62.</p><p class=\"entry-text\">② ficar a salvo de perigo, esquivando-se dele ou evitando-o, escapar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:52</a> (a acepção 1 também é provável); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:25</a> v.l. Com o acusativo daquilo de que se escapa (Artem. 1, 21; 4, 1 p. 200, 24; Jos., Vi. 94, Ant. 6, 344; Just., A I, 12, 11 <span class=\"greek\">ἄγνοιαν</span>) <span class=\"greek\">ἔφυγον</span> <span class=\"greek\">στόματα</span> <span class=\"greek\">μαχαίρης</span> 11:34. <span class=\"greek\">τὸ</span> <span class=\"greek\">αἰώνιον</span> (<span class=\"greek\">πῦρ</span>) MPol 2:3. Cf. 2 Cl 18:2. <span class=\"greek\">ἀπό</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:7</a>; 23:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:7</a> (cf. Il. 20, 350).—Precaver-se contra, com acus. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀπειλάς</span> as ameaças, isto é, os castigos que elas anunciam 1 Cl 58:1.</p><p class=\"entry-text\">③ abster-se de fazer algo, evitando-o por seu dano potencial, fugir de, evitar, esquivar-se de, extensão fig. de 1, e em sentido moral com acusativo da coisa (Zaleucus em Stob. IV p. 125, 12 H. <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδικίαν</span>; Cleobulus em Diog. L. 1, 92; Epict. 1, 7, 25; SIG 1268 I, 3 [III a.C.] <span class=\"greek\">ἄδικα</span> <span class=\"greek\">φεῦγε</span>; 4 Macc 8:19; Just., A I, 43, 3) <span class=\"greek\">φεύγετε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πορνείαν</span> (TestReub 5:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:18.</a> Em contraste com <span class=\"greek\">διώκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:11</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:22</a> (ao lado de <span class=\"greek\">διώκειν</span>, <span class=\"greek\">φεύγειν</span> <span class=\"greek\">τι</span> pode ter o sentido de ‘fugir de’ como no escólio sobre Nicander, Ther. 75).—1 Cl 30:1; 2 Cl 10:1; ITr 11:1; IPhld 2:1; 6:2; 7:2; ISm 7:2; IPol 5:1. Também <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (Sir 21:2 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἁμαρτίας</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:14</a>; B 4:1, 10; D 3:1; H 37, 3 v.l. (por <span class=\"greek\">ἀφέξῃ</span>).</p><p class=\"entry-text\">④ deixar de ser visível, sumir, desaparecer (Ps.-Clem., Hom. 2, 28) <span class=\"greek\">πᾶσα</span> <span class=\"greek\">νῆσος</span> <span class=\"greek\">ἔφυγεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:20.</a> Com <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τινός</span> (como Ps 67:2; cf. também Dt 28:7; Josh 8:5; contudo, igualmente já em Ctesias: 688 Fgm. 9, 1, 3 p. 454, 16 Jac. <span class=\"greek\">φυγεῖν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">Κύρου</span> e escólio sobre Nicander, Ther. 377 em citação livre de Herodas [8, 59] <span class=\"greek\">φεύγωμεν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">προσώπου</span>) 20:11. Ou o escritor enfatiza a cessação da existência, em vez da invisibilidade?—B. 698. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φῆλιξ, ικος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Φῆλιξ</span>, <span class=\"greek\">ικος</span>, <span class=\"greek\">ὁ</span> (ins: Sb 4601, 3 [144 d.C.]; APF II 442 n.º 56, 9 [II d.C.]; POxf 3, 1 [142 d.C.]; POxy 800 [153 d.C.]; índice de Joseph.; Just., A I, 29, 2f; sobre o acento B-D-F §13; Mlt-H. 57) Antônio Félix, liberto da casa dos Cláudios e irmão de Palas, o favorito do imperador Cláudio. Em 52/53 d.C. F. tornou-se procurador da Palestina. O ano de sua destituição é discutido (v. Schürer I, 465, 42; ESchwartz, NGG 1907, 284ff), mas foi por volta de 60. O caráter infame de sua administração contribuiu para preparar o terreno para a revolta de 66–70 (per omnem saevitiam ac libidinem jus regium servili ingenio exercuit, ‘deleitou-se na crueldade e na luxúria e exerceu o poder de um rei com a mentalidade de um escravo’: Tacitus, Hist. 5, 9). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:24,</a> 26; 24:3, 22, 24f, 27; 25:14.—Zahn, Einl. II3 647ff; Schürer I, 460ff; Pauly-W. I 2616–18; EMeyer III 47ff; BHHW I 469; índice de Haenchen.—Sobre a questão de se Pilatos (v. <span class=\"greek\">Πιλᾶτος</span> e <span class=\"greek\">Πόντιος</span>), Félix e Festo eram procuradores (v. <span class=\"greek\">ἐπίτροπος</span> 1) ou prefeitos (v. <span class=\"greek\">ἔπαρχος</span>), v. a inscrição latina de Cesareia descoberta e publicada pela primeira vez por AFrova, Istituto Lombardo Rendiconti 95, ’61 (v. também Schürer I, 358 nota 22, e 359), que oficialmente se refere a Pilatos como prefeito. É provável que, no tempo de Félix e Festo, isso tenha sido oficialmente mudado para procurador. Os termos eram por vezes empregados indistintamente.—Hemer, Acts 171–73; HTajra, The Trial of St. Paul ’89, 125–34.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φήμη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φήμη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; LXX; TestSol 8:1 D; JosAs 1:9; Just.; Ath.) relato, notícia <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">φήμη</span> <span class=\"greek\">αὕτη</span> espalhou-se a notícia disso (Jos., Bell. 2, 416; cf. Philo, Leg. ad Gai. 231) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:26.</a> <span class=\"greek\">φ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (Herodian 2, 1, 3; 2, 7, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:14.</a>—DELG s.v. <span class=\"greek\">φημί</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φημί</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φημί</span> 2.ª sg. <span class=\"greek\">φῄς</span> (Just.), 3.ª sg. <span class=\"greek\">φησίν</span>, 3.ª pl. <span class=\"greek\">φασίν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:10</a> v.l.; 3.ª sg. do imperf. e do 2.º aor. <span class=\"greek\">ἔφη</span> (v. Kühner-Bl. II 210), 3.ª pl. <span class=\"greek\">ἔφασαν</span> (Esth 10:31; Demetr.: 722 Fgm. 5 Jac. [Eus., PE 9, 29, 16]); fut. <span class=\"greek\">φήσω</span> (Just.); 1.º aor. 3.ª sg. <span class=\"greek\">ἔφησεν</span> 2 Macc 3:27 e outros lugares (Hom.+).</p><p class=\"entry-text\">① declarar algo oralmente ou por escrito, dizer, afirmar com discurso direto</p><p class=\"entry-text\">ⓐ com alternância entre primeira e terceira pessoas em diálogo Hv 2, 4, 1; 3, 2, 1; 3, 3, 1f e frequentemente.</p><p class=\"entry-text\">ⓑ introduzindo discurso direto</p><p class=\"entry-text\"><span class=\"greek\">α</span>. precedendo-o <span class=\"greek\">ὁ</span> <span class=\"greek\">δέ</span> <span class=\"greek\">φησιν</span>· <span class=\"greek\">οὔ</span>, <span class=\"greek\">μήποτε</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:29.</a> Cf. 26:61; 27:11, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:38</a>; 18:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:2</a>; 8:36; 10:30 e outros lugares. Frequentemente com dativo da pessoa a quem se dirige a palavra <span class=\"greek\">ἔφη</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span>· <span class=\"greek\">πάλιν</span> <span class=\"greek\">γέγραπται</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:7.</a> Cf. 13:28; 21:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:12</a>; 14:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:32.</a> Também <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> (TestAbr A 15 p. 96, 7 [Stone p. 40]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.70\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:70</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:28</a>; 16:37; 26:1.—Empregado com um particípio para denotar a natureza da declaração <span class=\"greek\">ἀποκριθεὶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἑκατόνταρχος</span> <span class=\"greek\">ἔφη</span>· <span class=\"greek\">κύριε</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:8.</a> Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:3,</a> 40.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. inserido depois da primeira palavra ou das primeiras palavras do discurso direto (Oenomaus em Eus., PE 6, 7, 8 <span class=\"greek\">ἀγγελῶ</span>, <span class=\"greek\">νὴ</span> <span class=\"greek\">Δία</span>, <span class=\"greek\">φήσει</span> <span class=\"greek\">τις</span>, …; TestJob 34:4; JosAs 24:8; Just., D. 1, 3) <span class=\"greek\">δός</span> <span class=\"greek\">μοι</span>, <span class=\"greek\">φησίν</span>, <span class=\"greek\">ὧδε</span> … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:8.</a> <span class=\"greek\">ποίας</span>; <span class=\"greek\">φησίν</span> 19:18 v.l. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:40</a> (aqui <span class=\"greek\">φησίν</span> está no final de uma citação direta de apenas duas palavras; cf. Just., D. 3, 7 <span class=\"greek\">οὐ</span> <span class=\"greek\">γάρ</span>, <span class=\"greek\">φημί</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:38</a> v.l.; 23:35; 25:5, 22; 26:25. <span class=\"greek\">ὡς</span> <span class=\"greek\">ἔφην</span> Papias (2:15) (ApcMos 42).</p><p class=\"entry-text\">ⓒ sem sujeito, quando este é evidente <span class=\"greek\">ὅρα</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">φησιν</span> <span class=\"greek\">ποιήσεις</span> <span class=\"greek\">πάντα</span> pois atenta para isto, diz (Deus) (Ex 25:40; Just., D. 126, 6; Mel., P. 12, 78; Ath. 32, 1), deves fazer tudo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5.</a> Mas <span class=\"greek\">φησίν</span> também se emprega impessoalmente, diz-se, de modo que pode acompanhar também um sujeito plural que faz uma declaração (cf. Demosth. 23, 31; ViJer 8 [p. 72, 12 Sch.]; Epict., Enchir. 24, 2; Maximus Tyr. 5, 4a) <span class=\"greek\">αἱ</span> <span class=\"greek\">ἐπιστολαὶ</span> <span class=\"greek\">μέν</span>, <span class=\"greek\">φησίν</span>, <span class=\"greek\">βαρεῖαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:10</a> (o sujeito dessa declaração é a oposição a Paulo na igreja de Corinto; daí a v.l. <span class=\"greek\">φασίν</span>). <span class=\"greek\">οὐ</span> <span class=\"greek\">δεῖν</span>, <span class=\"greek\">φησίν</span> (isto é, os gnósticos) <span class=\"greek\">προφήταις</span> <span class=\"greek\">χρῆσθαι</span> AcPlCor 1:10. Com citações das Escrituras <span class=\"greek\">φησίν</span> diz (<span class=\"greek\">φησίν</span> abs. com uma citação de Aratus: Synes., Prov. 2, 5 p. 125a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:16</a>; 1 Cl 30:2; 2 Cl 7:6; B 7:7.</p><p class=\"entry-text\">ⓓ <span class=\"greek\">φησίν</span>, ao introduzir citação das Escrituras, pode ser predicado de uma grande variedade de sujeitos (cf. <span class=\"greek\">φησὶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> Pla., Phil. 51c; Maximus Tyr. 22, 5b; Just., D. 93, 3) <span class=\"greek\">φησὶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἅγιος</span> <span class=\"greek\">λόγος</span> 1 Cl 13:3. (<span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span>) 16:2. <span class=\"greek\">αὐτός</span> (=<span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span>) <span class=\"greek\">φησιν</span> 16:15. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> 33:5. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐκλεκτὸς</span> <span class=\"greek\">Δαυίδ</span> 52:2.</p><p class=\"entry-text\">② dizer algo que oferece explicação mais completa de uma declaração, querer dizer com a própria declaração (Artem. 1, 67 p. 62, 16 <span class=\"greek\">φημὶ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐγώ</span>=mas quero dizer), com acus. (Diod S 37, 29, 5 <span class=\"greek\">Κράσσον</span> <span class=\"greek\">φημί</span>; Syntipas p. 10, 12) <span class=\"greek\">τοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:29</a>; cf. 10:15, 19. Seguido de <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:19</a> (Caecil. Calact., Fgm. 103 p. 93, 18 <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">φημι</span>; <span class=\"greek\">ὅτι</span> <span class=\"greek\">κτλ</span>.); <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ὅτι</span> 15:50. Seguido de acusativo e infinitivo (Synes., Kingship 15 p. 14c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:8</a>; Papias (3:2).—HFournier, Les verbes ‘dire’ en Grec ancien ’46. B. 1257. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φημίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φημίζω</span> 1.º aor. pass. <span class=\"greek\">ἐφημίσθην</span>; inf. perf. <span class=\"greek\">πεφημίσθαι</span> (de <span class=\"greek\">φημί</span> por meio de <span class=\"greek\">φῆμις</span> ‘fala’; Hes. e outros; SibOr 3, 2; 406) fazer uma notícia circular de boca em boca, difundir notícia/rumor (Jos., Bell. 1, 450) pass. ser objeto de rumor, espalhar-se como rumor (Aeschyl. e outros; Plut., Mor. 264d <span class=\"greek\">οἱ</span> <span class=\"greek\">τεθνάναι</span> <span class=\"greek\">φημισθέντες</span>=‘aqueles de quem se dizia que estavam mortos’; PGiss 19, 4 [II d.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:15</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:43</a> v.l. <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">πεφημίσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πόλει</span> porque já se espalhara um rumor pela cidade AcPl Ha 4, 17.—DELG s.v. <span class=\"greek\">φημί</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Φῆστος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Φῆστος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (PLond III, 904, 33 p. 126 [104 d.C.]; índice de Josephus) Pórcio Festo, sucessor de Félix (v. <span class=\"greek\">Φῆλιξ</span>) como procurador da Palestina. Nem o início nem o fim (por ocasião de sua morte) de seu mandato podem ser determinados com plena certeza, embora geralmente se suponha que tenha morrido no começo dos anos 60. Durante seu governo e com seu consentimento, Paulo foi ao tribunal imperial em Roma. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:27</a>; 25:1, 4, 9, 12–14, 22–24; 26:24f, 32.—Schürer I, 467f; Zahn, Einl. II3 647ff; ESchwartz, NGG 1907, 294ff; UHolzmeister, Der hl. Pls vor dem Richterstuhle des Festus: ZKT 36, 1912, 489–511; 742–82; ESpringer, D. Prozess des Ap. Pls: PJ 217, 1929, 182–96: Taubenschlag, OpMin II, 721–26 (pap); RJewett, A Chronology of Paul’s Life ’79; RCassidy, Society and Politics in the Acts of the Apostles ’87; Pauly-W. XXII, 200–227; BHHW I 479; índice de Haenchen.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθάνω</span> 1.º aor. <span class=\"greek\">ἔφθασα</span>; perf. 3.ª sg. <span class=\"greek\">ἔφθακεν</span> SSol 2:12. (Hom.+) primariamente ‘chegar ou fazer algo primeiro ou antes de alguém’.</p><p class=\"entry-text\">① antecipar-se ao mover-se para uma posição, vir antes, preceder (exemplos do período posterior, inclusive ins e pap, em Clark [v. abaixo] 375f) com acusativo da pessoa a quem se precede (Diod S 15, 61, 4 <span class=\"greek\">τοὺς</span> <span class=\"greek\">πολεμίους</span>; Appian, Syr. 29 §142, Bell. Civ. 5, 30 §115; SIG 783, 35 [27 a.C.] <span class=\"greek\">φθάνοντες</span> <span class=\"greek\">ἀλλήλους</span>; Wsd 6:13; Jos., Ant. 7, 247) <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">φθάσωμεν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">κοιμηθέντας</span> de modo algum precederemos os que adormeceram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:15.</a></p><p class=\"entry-text\">② chegar a uma posição ou alcançá-la, ter acabado de chegar, depois simplesmente chegar, alcançar (grego tardio e moderno: Plut., Mor. 210e; 338a; Vett. Val. 137, 35; 174, 12 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ποῖον</span> [<span class=\"greek\">ἀστέρα</span>]; Herm. Wr. 9, 10; PParis 18, 14 [II d.C.] <span class=\"greek\">φθάσομεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Πελούσιον</span>; PGM 3, 590; LXX [cf. Thackeray p. 288f]; TestAbr A 1 p. 77, 9 [Stone p. 2]; TestAbr B 2 p. 107, 3 e outros lugares [St. p. 62]; TestReub 5:7; TestNapht 6:9 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span> [v.l. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆν</span>]; JosAs 26:5 AB; Philo, Op. M. 5, Leg. All. 3, 215 <span class=\"greek\">φθάσαι</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">θεοῦ</span>, Conf. Lingu. 153, Mos. 1, 2.—JVogeser, Zur Sprache der griech. Heiligenlegenden, diss. Munique 1907, 46; JWittmann, Sprachl. Untersuchungen zu Cosmas Indicopleustes, diss. Munique 1913, 16) <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> sobrevir a alguém, alcançar, talvez com uma sugestão de êxito (em sentido adverso, DDaube, The Sudden in Scripture, ’64, 35f). <span class=\"greek\">ἄρα</span> <span class=\"greek\">ἔφθασεν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλεία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:20</a> (KClark, JBL 59, ’40, 367–83 <span class=\"greek\">ἐγγίζειν</span> e <span class=\"greek\">φθ</span>.; HMartin, ET 52, ’40/41, 270–75). <span class=\"greek\">ἔφθασεν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀργή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:16</a> (cf. Eccl 8:14a v.l.; TestLevi 6:11). <span class=\"greek\">ἄχρι</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐφθάσαμεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:14</a> (SAndrews, SBLSP 36, ’97, 479 n. 30: talvez uma alusão à condecoração militar ‘corona militaris’).</p><p class=\"entry-text\">③ chegar a determinado estado, atingir <span class=\"greek\">φθ</span>. <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> chegar a, alcançar, atingir algo (BGU 522, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:16.</a>—B. 701f; 703. DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθαρ-</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθαρ</span>- v. <span class=\"greek\">φθείρω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθαρτός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθαρτός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">φθείρω</span>) sujeito à deterioração/destruição, perecível (Aristot., Anal. 2, 22; Diod S 1, 6, 3 [<span class=\"greek\">γεννητὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φθαρτός</span> em contraste com <span class=\"greek\">ἀγέννητος</span> e <span class=\"greek\">ἄφθαρτος</span>; assim também Just. D. 5, 4]; Plut., Mor. 106d; 717e; Sext. Emp., Math. 9, 141; TestAbr A 4 p. 81, 18 [Stone p. 10]; Philo, Leg. All. 2, 3, Cher. 5; 48 <span class=\"greek\">χρυσὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄργυρος</span>, <span class=\"greek\">οὐσίαι</span> <span class=\"greek\">φθαρταί</span>; 2 Macc 7:16; apologistas, exceto Tat.) de pessoas, mortal <span class=\"greek\">ἄνθρωπος</span> (Ps.-Callisth. 2, 22, 12; Philo, Somn. 1, 172) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:23</a>; Hs 9, 23, 4. De coisas <span class=\"greek\">στέφανος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:25.</a> <span class=\"greek\">σπορά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:23.</a> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐνθάδε</span> 2 Cl 6:6. <span class=\"greek\">ἀγῶνες</span> competições perecíveis, isto é, competições por um prêmio perecível 7:1, 4. <span class=\"greek\">τὸ</span> <span class=\"greek\">κατοικητήριον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">φθαρτὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀσθενές</span> B 16:7. <span class=\"greek\">ὕλη</span> (Wsd 9:15 <span class=\"greek\">σῶμα</span>) Dg 2:3. <span class=\"greek\">σάρξ</span> Hs 5, 7, 2 (Philo, Congr. Erud. Grat. 112).—Subst. <span class=\"greek\">οἱ</span> <span class=\"greek\">φ</span>. os perecíveis dentre a humanidade Dg 9:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">φ</span>. (Wsd 14:8; Philo, Op. M. 82) <span class=\"greek\">τὸ</span> <span class=\"greek\">φθαρτὸν</span> <span class=\"greek\">τοῦτο</span> esta (natureza) perecível <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.53\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:53f.</a> <span class=\"greek\">τὰ</span> <span class=\"greek\">φθ</span>. coisas perecíveis (Test Benj 6:2; Philo, Ebr. 209 [oposto a <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄφθαρτα</span>]; Just., A II, 7, 9; Ath. 15, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:18</a>; B 19:8; Dg 6:8.—DELG s.v. <span class=\"greek\">φθείρω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθέγγομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθέγγομαι</span> médio depoente fut. <span class=\"greek\">φθέγξομαι</span> LXX; 1.º aor. <span class=\"greek\">ἐφθεγξάμην</span> (Hom.+; SIG 1175, 6 <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">μοχθηρὸν</span> <span class=\"greek\">φθ</span>.; 23 [abs.]; PFlor 309, 10; LXX; TestJob 18:4; Just.; Tat. 1, 2) lit. ‘produzir um som’ (Iren. 1, 14, 7 [Harv. I, 142, 4]), depois ‘clamar em voz alta’ (Orig., C. Cels. 7, 55, 3), em geral falar, proferir, proclamar <span class=\"greek\">τὶ</span> algo, com ênfase no ato de proferir (Lucian, Nigrin. 3, 11; Iambl. Erot. 21; Sextus 356; Wsd 1:8 <span class=\"greek\">ἄδικα</span>; TestDan 5:2 <span class=\"greek\">ἀλήθειαν</span>; Philo; Jos., Bell. 2, 128, C. Ap. 2, 219) <span class=\"greek\">ὑπέρογκα</span> falar de modo bombástico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:18.</a> De um animal <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">φωνῇ</span> v. 16 (Alciphron 4, 19, 3 <span class=\"greek\">εἰ</span> <span class=\"greek\">βοῦς</span> <span class=\"greek\">μοι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λεγόμενον</span> <span class=\"greek\">φθέγξαιτο</span>). Abs., de pessoas (oposto a ‘calar-se’.—X., An. 6, 6, 28, Cyr. 7, 3, 11; Ael. Aristid. 30, 19 K.=10 p. 121 D.; TestJob 18:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:18.</a>—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθείρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθείρω</span> fut. <span class=\"greek\">φθερῶ</span>; 1.º aor. <span class=\"greek\">ἔφθειρα</span>. Pass.: 2.º fut. <span class=\"greek\">φθαρήσομαι</span>; 2.º aor. <span class=\"greek\">ἐφθάρην</span>; perf. <span class=\"greek\">ἔφθαρμαι</span>, part. <span class=\"greek\">ἐφθαρμένος</span> (Hom.+; ins, pap, LXX, TestJob 33:4; Test12Patr; ParJer 7:26; Philo, Ar., Just., Tat.) em geral ‘destruir, arruinar’</p><p class=\"entry-text\">① causar dano de maneira física ou nas circunstâncias externas, destruir, arruinar, corromper, estragar</p><p class=\"entry-text\">ⓐ arruinar financeiramente <span class=\"greek\">τινά</span> alguém, assim talvez em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:2</a> (v. 2a abaixo).</p><p class=\"entry-text\">ⓑ A expressão <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ναὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φθείρει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:17</a> parece derivar da ideia da destruição de uma casa (X., Mem. 1, 5, 3 <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐαυτοῦ</span> <span class=\"greek\">φθείρειν</span>. Frequentemente em contratos matrimoniais: Mitt-Wilck. I/2, 284, 11 [II a.C.]; PTebt 104, 29 [92 a.C.] e outros).</p><p class=\"entry-text\">ⓒ seduzir uma virgem (Eur. e outros; Demetr.: 722 Fgm. 1, 9 Jac.; Diod S 1, 23, 4; Jos., Ant. 4, 252; Just., A I, 9, 4) <span class=\"greek\">οὐθὲ</span> <span class=\"greek\">Εὔα</span> <span class=\"greek\">φθείρεται</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">παρθένος</span> <span class=\"greek\">πιστεύεται</span> nem Eva é corrompida; em vez disso, confia-se em uma virgem Dg 12:8 (<span class=\"greek\">πιστεύω</span> 1f).</p><p class=\"entry-text\">ⓓ pass. ser arruinado, estar destinado à destruição pela transitoriedade terrena ou de outro modo (Epict. 2, 5, 12 <span class=\"greek\">τὸ</span> <span class=\"greek\">γενόμενον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φθαρῆναι</span> <span class=\"greek\">δεῖ</span>; TestJob 33:4 <span class=\"greek\">ἡ</span> <span class=\"greek\">δόξα</span> <span class=\"greek\">αὐτοῦ</span> [<span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>] <span class=\"greek\">φθαρήσεται</span>; Just., A II, 11, 5 <span class=\"greek\">κάλλει</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ῥέοντι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φθειρομένῳ</span>) de imagens cultuais Dg 2:4. De um homem curvado pela velhice <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">ἐφθαρμένον</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προτέρων</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πράξεων</span> seu espírito, que já degenerara de sua condição anterior (v. <span class=\"greek\">πρᾶξις</span> 6) Hv 3, 12, 2 (cf. Ocellus [II a.C.] c. 23 Harder [1926] <span class=\"greek\">φθείρονται</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀλλήλων</span>).</p><p class=\"entry-text\">② causar deterioração da vida interior, arruinar, corromper</p><p class=\"entry-text\">ⓐ arruinar ou corromper <span class=\"greek\">τινά</span> alguém, por ensinamento errôneo ou imoralidade, assim talvez em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:2</a> (v. 1a acima). <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἔφθειρεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> (=<span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀνθρώπους</span>; v. <span class=\"greek\">γῆ</span> 2) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πορνείᾳ</span> <span class=\"greek\">αὐτῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:2.</a> Pass. (UPZ 20, 17 [163 a.C.]; TestJud 19:4 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁμαρτίαις</span> <span class=\"greek\">φθαρείς</span>) <span class=\"greek\">τὸν</span> <span class=\"greek\">παλαιὸν</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">φθειρόμενον</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐπιθυμίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:22.</a> Cf. Hs 8, 9, 3 v.l.</p><p class=\"entry-text\">ⓑ arruinar ou corromper <span class=\"greek\">τὶ</span> algo por meios enganosos <span class=\"greek\">πίστιν</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κακῇ</span> <span class=\"greek\">διδασκαλίᾳ</span> IEph 16:2. A <span class=\"greek\">ἐκκλησία</span> (oposto a <span class=\"greek\">τηρεῖν</span>) 2 Cl 14:3ab. Sobre <span class=\"greek\">φθείρουσιν</span> <span class=\"greek\">ἤθη</span> <span class=\"greek\">χρηστὰ</span> <span class=\"greek\">ὁμιλίαι</span> <span class=\"greek\">κακαί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:33</a> cf. <span class=\"greek\">ἦθος</span>. Pass. ser desviado (Jos., Bell. 4, 510) <span class=\"greek\">μήπως</span> <span class=\"greek\">φθαρῇ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">νοήματα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπλότητος</span> (<span class=\"greek\">νόημα</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:3</a> (<span class=\"greek\">φθ</span>. da sedução de uma virgem, v. 1c acima).</p><p class=\"entry-text\">③ infligir castigo, destruir no sentido de ‘castigar com destruição eterna’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:17b</a> (=‘castigar destruindo’ como em Jer 13:9). Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:12</a>; Jd 10. <span class=\"greek\">ἔφθαρται</span> (com <span class=\"greek\">ἀπώλετο</span>) IPol 5:2.</p><p class=\"entry-text\">④ infringir as regras de uma competição, violar regras, <span class=\"greek\">ἀγῶνα</span> <span class=\"greek\">φθείρειν</span> termo técnico (SIG 1076, 3) 2 Cl 7:4; cf. v. 5 (aqui em imagem).—B. 758. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθινοπωρινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθινοπωρινός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">φθινόπωρον</span>, ‘do fim do outono’, de <span class=\"greek\">φθίνω</span> e <span class=\"greek\">ὀπώρα</span>) pertencente ao fim do outono (Aristot., HA 5, 11; Polyb. 4, 37, 2; Plut., Mor. 735b <span class=\"greek\">ὁ</span> <span class=\"greek\">φθινοπωρινὸς</span> <span class=\"greek\">ἀήρ</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">φυλλοχοεῖ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δένδρα</span>; Aelian, NA 14, 26 p. 358, 24; PHib 27, 170 [III a.C.]). Em Jd 12 os mestres facciosos são chamados <span class=\"greek\">δένδρα</span> <span class=\"greek\">φθινοπωρινὰ</span> <span class=\"greek\">ἄκαρπα</span> árvores no fim do outono, sem fruto (com <span class=\"greek\">νεφέλαι</span> <span class=\"greek\">ἄνυδροι</span>). O ponto da comparação é provavelmente que árvores sem fruto na época da colheita (v. JMayor, <span class=\"greek\">φθινοπωρινός</span>: Exp. 6.ª série, 9, 1904, 98–104, The Ep. of St. Jude and 2 Pt 1907, 55–59) não cumpriram o propósito para o qual existem, assim como as nuvens sem água.—B. 1015. DELG s.v. <span class=\"greek\">φθίνω</span>. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθόγγος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθόγγος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">φθέγγομαι</span>; Hom.+; PGM 7, 775; 778; Philo) qualquer som claro ou distinto</p><p class=\"entry-text\">ⓐ de instrumentos musicais, tom (Pla., Leg. 812d; Philostrat., Vi. Apoll. 5, 21 p. 181, 19.—Wsd 19:18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:7.</a></p><p class=\"entry-text\">ⓑ da voz humana (Hom. e outros) <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">φθόγγος</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:18</a> (cf. Ps 18:5).—DELG s.v. <span class=\"greek\">φθέγγομαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθονέω</span> (<span class=\"greek\">φθόνος</span>) 1.º aor. <span class=\"greek\">ἐφθόνησα</span> (Hom.+; ins; PFlor 273, 5; Tob 4:7; 16; TestSol 1:2 A; Test12Patr, JosAs; GrBar 4:8; ApcEsdr 5:3 p. 29, 26 Tdf.; ApcMos 18; Philo; Just., A I, 31, 7 [<span class=\"greek\">φθονούμενος</span>]; Tat. 1, 1) invejar, ter ciúme <span class=\"greek\">τινί</span> (de) alguém (X., Mem. 3, 5, 16; Chares [IV a.C.] 1 [Anth. Lyr.2 Diehl, Suppl. ’42]; Herodian 3, 2, 3; Jos., Vi. 230) <span class=\"greek\">ἀλλήλοις</span> (Plut., Artox. 24, 7 v.l.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:26</a> (v.l. <span class=\"greek\">ἀλλήλους</span>; o acus. como em JosAs 24:2; Aesop 184, 1 H.=117P.//119 H-H.); com inf. (Appian, Bell. Civ. 4, 95 §400 <span class=\"greek\">φθ</span>. <span class=\"greek\">τινι</span> com inf.=invejar a alguém [a oportunidade de]; Jos., C. Ap. 2, 268) <span class=\"greek\">μὴ</span> <span class=\"greek\">φθονήσωμεν</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">τυχεῖν</span> <span class=\"greek\">τοσούτων</span> <span class=\"greek\">ἀγαθῶν</span> não invejemos uns aos outros a obtenção de tantos benefícios 2 Cl 15:5 (ApcMos 18 <span class=\"greek\">τοῦτο</span> … <span class=\"greek\">ἐφθόνησεν</span> <span class=\"greek\">ὑμῖν</span>; Jos., Ant. 4, 235 <span class=\"greek\">ἀγαθῶν</span> <span class=\"greek\">φθονεῖν</span> <span class=\"greek\">τινι</span>; ApcEsdr 5:3 <span class=\"greek\">αὕτη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">γάλα</span> <span class=\"greek\">ἐφθόνησεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δοῦναι</span> ‘reter’).—<span class=\"greek\">φθ</span>. <span class=\"greek\">τινι</span> também pode significar não gostar de alguém, ressentir-se de alguém sem a conotação de ciúme ou rancor (Appian, Bell. Civ. 1, 79 §360). Abs. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:2</a> v.l.—DELG s.v. <span class=\"greek\">φθόνος</span>. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθόνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθόνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Pind., Hdt. e outros; Demosth. 20, 165 oposto a <span class=\"greek\">φιλανθρωπία</span>; Ael. Aristid. 29, 5 K.=40 p. 752 D.: <span class=\"greek\">φθ</span>. como <span class=\"greek\">ἔσχατον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρωπίνων</span> <span class=\"greek\">ἁμαρτημάτων</span>; pap; ins frequentemente associadas ao ‘mau-olhado’ [v. Elliott s.v. <span class=\"greek\">βασκαίνω</span> 1], referências SEG XLI, 1526; LXX, pseudep.; Philo; Jos., Vi. 80; 122; Just.; Tat. 32, 3) inveja, ciúme, com <span class=\"greek\">ζῆλος</span> (1 Macc 8:16; TestSim 4:5) 1 Cl 3:2; 4:7; 5:2. <span class=\"greek\">διὰ</span> <span class=\"greek\">ζῆλος</span> <span class=\"greek\">Δαυὶδ</span> <span class=\"greek\">φθόνον</span> <span class=\"greek\">ἔσχεν</span> … <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">Σαοὺλ</span> Saul invejou Davi por ciúme. Com <span class=\"greek\">κακία</span> (TestBenj 8:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:3.</a> Em catálogos de vícios (em alguns dos quais também ocorre <span class=\"greek\">κακία</span>; v. também Herm. Wr. 13, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:29</a> (<span class=\"greek\">μεστοὺς</span> <span class=\"greek\">φθόνου</span> <span class=\"greek\">φόνου</span> <span class=\"greek\">ἔριδος</span>. O jogo de palavras <span class=\"greek\">φθόν</span>. <span class=\"greek\">φόν</span>. como em Eur., Tro. 766ff); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:4</a> (com <span class=\"greek\">ἔρις</span>); <span class=\"greek\">φθόνοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:21</a> (v.l. + <span class=\"greek\">φόνοι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:1.</a> <span class=\"greek\">διὰ</span> <span class=\"greek\">φθόνον</span> por inveja (Anaximenes [IV a.C.]: 72 Fgm. 33 Jac.; Philo, Mos. 1, 2; Jos., Vi. 204 <span class=\"greek\">ἐπιγνοὺς</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">φθόνον</span> <span class=\"greek\">ἀναιρεθῆναί</span> <span class=\"greek\">με</span> <span class=\"greek\">προστάξαι</span>, C. Ap. 1, 222) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:15</a> (com <span class=\"greek\">ἔρις</span>). Sobre a passagem difícil e talvez textualmente corrompida <span class=\"greek\">πρὸς</span> <span class=\"greek\">φθόνον</span> (Demosth. 20, 165) <span class=\"greek\">ἐπιποθεῖ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:5</a> v. <span class=\"greek\">ἐπιποθέω</span>; <span class=\"greek\">πρός</span> 3f, e também FSpitta, Der Brief des Jk (=Zur Gesch. und Lit. des Urchristentums II) 1896, 118ff; PCorssen, GGA 1893, 596f; OKirn, StKr 77, 1904, 127ff; 593ff; CBruston, RTQR 11, 1907, 368–77; JFindlay, ET 37, 1926, 381f; AMeyer, D. Rätsel des Jk 1930, 258f; LJohnson, NovT 25, ’83, 327–47 (Js 3:13–4:10; literatura greco-romana)—B. 1139. DELG. M-M. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθορά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθορά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (Aeschyl., Hdt.+; ins, pap, LXX, En; PsSol 4:6; SibOr 2, 9; Philo; Jos., Ant. 18, 373; Mel., P. 49, 351; Ath., R. 16 p. 67, 24 e outros lugares)</p><p class=\"entry-text\">① decomposição de matéria orgânica, dissolução, deterioração, corrupção, no mundo da natureza (Galen, In Hippocr. De Natura Hominis Comm. 45 p. 25, 6 Mewaldt <span class=\"greek\">γένεσις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φθορά</span>=vir à existência e perecer; 51 p. 28, 11 <span class=\"greek\">γένεσις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φθορὰ</span> <span class=\"greek\">σώματος</span>.—A causa da destruição é esclarecida por um acréscimo. Cf. Plut., Artox. 1019 [16, 6] a respeito de Mitrídates, que foi deixado decompor-se ainda vivo: <span class=\"greek\">εὐλαὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σκώληκες</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">φθορᾶς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σηπεδόνος</span> <span class=\"greek\">ἀναζέουσιν</span>=larvas e vermes pululavam em consequência da destruição e putrefação [de seu corpo]) <span class=\"greek\">τροφὴ</span> <span class=\"greek\">φθορᾶς</span> alimento perecível IRo 7:3. <span class=\"greek\">ἅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φθορὰν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀποχρήσει</span> tudo isso está destinado à destruição pelo consumo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:22.</a> De animais destinados a ser mortos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:12a</a> (X., Cyr. 7, 5, 64; Artem. 1, 78 p. 74, 27.—O escólio sobre Nicander, Ther. 795 explica <span class=\"greek\">κακόφθορα</span> dizendo que designa animais <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κακῇ</span> <span class=\"greek\">φθορᾷ</span> <span class=\"greek\">τεχθέντα</span>=nascidos para chegar a um fim funesto, isto é, à destruição).—Do estado de ser perecível (oposto a <span class=\"greek\">ἀφθαρσία</span> como em Philo, Mos. 2, 194; Mel., Ath.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.42\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:42</a>; também concretamente, aquilo que é perecível v. 50. <span class=\"greek\">ἡ</span> <span class=\"greek\">δουλεία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φθορᾶς</span> escravidão à corrupção <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:21.</a> [<span class=\"greek\">ἀπ</span>]<span class=\"greek\">ὸ</span> <span class=\"greek\">φθορᾶς</span> <span class=\"greek\">γεγ</span>[<span class=\"greek\">ονός</span>] aquilo que provém do perecível Ox 1081 13f (=copta SJCh 89, 11f; a restauração <span class=\"greek\">φθορᾶς</span> pap linha 12 também corresponde à versão copta; para a restauração correta de pap linha 23 v. sob <span class=\"greek\">διαφορά</span>).</p><p class=\"entry-text\">② destruição de um feto, aborto (cf. SIG 1042, 7 [II/III d.C.] <span class=\"greek\">φθορά</span>=aborto espontâneo [que torna a mãe impura por 40 dias] e <span class=\"greek\">φθόριον</span>=meio de provocar aborto) <span class=\"greek\">οὐ</span> <span class=\"greek\">φονεύσεις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φθορᾷ</span> B 19:5; D 2:2.—Sobre o tema do aborto v. Soranus, Gyn. 64f (procedimentos); Plut., Mor. 242c (<span class=\"greek\">διαφθείρω</span>); SDickison, Abortion in Antiquity: Arethusa 6, ’73, 159–66.</p><p class=\"entry-text\">③ ruína de uma pessoa por meio de um ato imoral, sedução de uma jovem (Demetr.: 722 Fgm. 1, 9 Jac.; Diod S 3, 59, 1; 5, 62, 1; Plut., Mor. 712c; Jos., Ant. 17, 309, C. Ap. 2, 202) com <span class=\"greek\">μοιχεία</span> (Philo, Det. Pot. Ins. 102) 2 Cl 6:4.</p><p class=\"entry-text\">④ depravação interior, depravação (Ex 18:18; Mi 2:10) <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐπιθυμίᾳ</span> <span class=\"greek\">φθορά</span> a depravação que existe no mundo por causa do desejo desordenado (oposto a <span class=\"greek\">θεία</span> <span class=\"greek\">φύσις</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:4.</a> <span class=\"greek\">δοῦλοι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φθορᾶς</span> 2:19. O v. 12b (v. 5 abaixo) dificilmente pertence aqui.</p><p class=\"entry-text\">⑤ destruição total de uma entidade, destruição nos últimos dias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:8</a> (oposto a <span class=\"greek\">ζωὴ</span> <span class=\"greek\">αἰώνιος</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φθορᾷ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φθαρήσονται</span> quando eles (os animais irracionais) forem destruídos no vindouro fim do mundo, estes (os falsos mestres) também serão destruídos (assim BWeiss, Kühl, JMayor, Windisch, Knopf, Vrede) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:12b.</a>—DELG s.v. <span class=\"greek\">θείρω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθορεύς, έως, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθορεύς</span>, <span class=\"greek\">έως</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">φθορά</span>) sedutor (Plut., Mor. 18c; Epict. 2, 22, 28 [com <span class=\"greek\">μοιχός</span>]; 4 Macc 18:8; Philo, Decal. 168 [com <span class=\"greek\">μοιχός</span>]; Tat. 33, 3) esta acepção deve ser preferida para B 10:7 e provavelmente também para 20:2; D 5:2, onde frequentemente se entende a palavra como abortista (cf. <span class=\"greek\">φθορά</span> 2).—D 16:3 é corruptor em geral.—DELG s.v. <span class=\"greek\">φθείρω</span> B.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0376-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φθοριμαῖος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φθοριμαῖος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (também Eus.) destrutivo <span class=\"greek\">οἵτινες</span> <span class=\"greek\">τήν</span> <span class=\"greek\">τινων</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἀνατρέπουσιν</span> <span class=\"greek\">φθοριμαίοις</span> <span class=\"greek\">λόγοις</span> que transtornam a fé de alguns mediante declarações destrutivas AcPl Cor 1:2 (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:18</a>).</p></section></article>"};
